"""Write the engine-neutral layer/state contract and preview travel metadata."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
factions={}
for faction in ['USMC','Russian']:
 j=json.loads((ROOT/'validation'/f'{faction}-authoring.json').read_text());clips={}
 for name,info in j['actions'].items():clips[name]={k:v for k,v in info.items()if k not in ['plant_samples','bones']}
 factions[faction]={'model':f'models/{faction}_Animated.glb','source':f'source/{faction}_Animation.blend','clips':clips}
refs=json.loads((ROOT/'validation/USMC-authoring.json').read_text());other=json.loads((ROOT/'validation/Russian-authoring.json').read_text());assert refs['rest_bones']==other['rest_bones']
states={'Idle':['Lower_Idle','Upper_LowReady'],'Walk':['Lower_Walk','Upper_LowReady'],'Sprint':['Lower_Sprint','Upper_Sprint'],'Stop':['Stop_Walk','Upper_LowReady'],'TurnLeft':['Turn_Left','Upper_Turn_Left'],'TurnRight':['Turn_Right','Upper_Turn_Right'],'Raise':['Lower_AimStance','Weapon_Raise'],'Lower':['Lower_AimStance','Weapon_Lower'],'AimIdle':['Lower_AimStance','Upper_Aim'],'StationaryFire':['Lower_AimStance','Upper_Aim','Recoil_Shot'],'AimWalk':['Lower_AimWalk','Upper_Aim'],'MovingFire':['Lower_AimWalk','Upper_Aim','Recoil_Shot'],'Reload':['Lower_AimStance','Reload']}
j={'version':1,'source_fps':30,'skeleton':{'bones':163,'rest_hash_sha256':hashlib.sha256(json.dumps(refs['rest_bones'],sort_keys=True).encode()).hexdigest(),'names_and_parents':{n:v['parent']for n,v in refs['rest_bones'].items()}},'coordinates':{'Blender':'metres, Z up, forward -Y','glTF':'metres, Y up, forward +Z'},'layers':{'lower':refs['actions']['Lower_Walk']['bones'],'upper':refs['actions']['Upper_Aim']['bones'],'recoil':refs['actions']['Recoil_Shot']['bones']},'states':states,'recoil':{'clip':'Recoil_Shot','reference_clip':'Upper_Aim','reference_frame':0,'blend':'quaternion additive; translation delta','demo_shot_interval_seconds':.14,'locomotion_phase_reset':False,'recovery_seconds':.2},'travel':{'loops':'Integrate documented speed along actor forward; clips are in place.','transitions':'Integrate travel_samples_m; entry/exit are at gait phase zero.','turns':'Commit actor yaw on completion and simultaneously switch the lower layer to Lower_Idle.','firing':'Keep the lower Action/time unchanged when firing starts or stops.'},'transition_policy':{'idle_to_walk':'Start_Walk','walk_to_idle':'Stop_Walk','walk_to_sprint':'Walk_To_Sprint','sprint_to_walk':'Sprint_To_Walk','sprint_to_idle':'Sprint_Stop','required_entry_phase':0,'weapon_raise':'play Weapon_Raise then Upper_Aim','weapon_lower':'play Weapon_Lower then Upper_LowReady','reload':'complete the exchange; commit identical seated magazine presentation without interpolating object ownership, then return to Upper_Aim; arbitrary interruption requires a separate policy'},'footstep_phases':[0,.5],'factions':factions,'limits':['No battle renderer, AI or gameplay integration.','Reloads are tactical magazine exchanges; internal bolt/trigger parts are not articulated.','Slope adaptation, foot terrain IK and locomotion at arbitrary speeds are not validated.','FBX files contain a flattened moving-fire take; all reusable layers are in GLB and Blender.']}
(ROOT/'architecture.json').write_text(json.dumps(j,indent=2)+'\n');print('PACKAGED_SHARED_ANIMATION_CONTRACT')
